def enhance(html):
    replacements=[
        ('<button data-view="research">Research</button>','<button data-view="value">GPU value</button><button data-view="research">Research</button>'),
        ("({explore,research,methods,downloads})","({explore,value:valuePage,research,methods,downloads})"),
        ("['explore','research','methods','downloads'].includes(requested)","['explore','value','research','methods','downloads'].includes(requested)")
    ]
    for old,new in replacements:
        if html.count(old)!=1:raise ValueError("Value insertion marker changed: "+old)
        html=html.replace(old,new)
    return html.replace("</style>",CSS+"</style>").replace("</script>",JS+"</script>")
